    "unitId": "n1:task-comprehension:2015-07:3:line-2",
    "text": "あのう、わたし、来月の十日に、この授業で発表することになってるんですが。実は、その日、国から両親が来日することになりまして．．．日本ははじめてで、日本語がまったくできないので、わたしが空港まで迎えに行く必要があって、授業を欠席させていただきたいのですが、発表もありますし。どうしたらよいかと思いまして．．．",
    "textVersion": "sha256:c450e488a19fc50ec9a7cd10594bf77f70fd90ed9fed2deb17a688179e21a54a",
