    "unitId": "n1:task-comprehension:2015-07:6:line-5",
    "text": "それから、異業種の人と交流することってすごく大事だよ。ほかの業界でいま何が話題なのか、どういうニーズがどこにあるか、世間話をしてる中から学べるからね。僕にとっては一番の情報源だよ。まあ、人脈作りに時間がかかるから、来週までにっていうのはちょっとね。",
